import React, { useState } from 'react';

const StrategyInspector = () => {
  const [strategyId, setStrategyId] = useState('');
  const [seed, setSeed] = useState(42);
  const [inspectionResult, setInspectionResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleInspectStrategy = async () => {
    setLoading(true);
    setError(null);
    setInspectionResult(null);

    try {
      const response = await fetch('http://localhost:8000/inspect_strategy', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          strategy_id: strategyId,
          seed: Number(seed),
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to inspect strategy');
      }

      const data = await response.json();
      setInspectionResult(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-4">
      <h2 className="text-2xl font-semibold mb-4">Strategy Inspector</h2>

      <div className="mb-4">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="strategy_id">
          Strategy ID:
        </label>
        <input
          type="text"
          id="strategy_id"
          className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
          value={strategyId}
          onChange={(e) => setStrategyId(e.target.value)}
        />
      </div>

      <div className="mb-6">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="seed_inspect">
          Seed:
        </label>
        <input
          type="number"
          id="seed_inspect"
          className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
          value={seed}
          onChange={(e) => setSeed(e.target.value)}
        />
      </div>

      <button
        className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
        onClick={handleInspectStrategy}
        disabled={loading}
      >
        {loading ? 'Inspecting...' : 'Inspect Strategy'}
      </button>

      {error && <p className="text-red-500 mt-4">Error: {error}</p>}

      {inspectionResult && (
        <div className="mt-6">
          <h3 className="text-xl font-semibold mb-3">Metrics</h3>
          <div className="bg-gray-50 p-4 rounded-md">
            <pre className="text-sm text-gray-800">{JSON.stringify(inspectionResult.metrics, null, 2)}</pre>
          </div>

          <h3 className="text-xl font-semibold mt-6 mb-3">Execution Trace</h3>
          <div className="bg-gray-50 p-4 rounded-md max-h-60 overflow-y-auto">
            {inspectionResult.execution_trace.length > 0 ? (
              <ul className="list-disc list-inside text-sm text-gray-800">
                {inspectionResult.execution_trace.map((trace, index) => (
                  <li key={index}>Step {trace.step}: {trace.event}</li>
                ))}
              </ul>
            ) : (
              <p>No execution trace available.</p>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default StrategyInspector;
